question:
Hàm sau trả về gì khi gọi `subsets([1, 2])`?
`function subsets(nums) {
  const result = [];
  const path = [];
  function bt(start) {
    result.push(path);
    for (let i = start; i < nums.length; i++) {
      path.push(nums[i]); bt(i + 1); path.pop();
    }
  }
  bt(0);
  return result;
}`

